"""Writes the prompt files of the routines round: eight directions, dark and light.
Usage: python3 prompts.py   (writes <slug>-<theme>.txt beside itself)"""
from pathlib import Path
R = Path(__file__).parent

HEAD = """UI design mockup of the project screen of an AI software factory console, in its existing "Mission control" design: a near-black blue room (dark) or a warm cream day version (light), thin-bordered instrument panels with small corner marks, cyan as the system colour, amber as the one signal that needs a person, monospace figures, everything exact and calm. Desktop browser viewport, 16:9, flat, no browser chrome, no device frame, the screen fills the whole image.

The shell is fixed and must look like this: a quiet top bar ("Factory console", the project "ai-software-factory-code", links "Board", "New task", "Projects", "Resources", "Costs", "Policy", "Alerts", a small moon-and-sun theme selector in a thin frame, "sebastian", "Log out"); under it the pulse band, one panel with the sentence "Two cards need your decision; #612's merge carries a migration." with an amber warning sign and a 3 px amber left rule, and under the sentence the instrument strip "● waiting on you | 3 working | 2 need you | €61.40 / €120.00 ▬▬▬▭▭ 51 % | GitHub: 1 open pull request | ▾"; then the main area: the chat on the left taking 40 percent of the width as the main region, with a narrow mono table of threads at its left edge ("Inbox" first with a small house mark, "Plan: the members page" with a cyan dot, "Session store: Postgres" as the open row, "Costs read: the date window") and the open thread's log and composer at its right (the box "Ask or tell the project…", "Send", small chips "/compact" "/new", and a small level button "assisted" under Send); and the board on the right taking 60 percent with its header row "Board", a small mono text box "Find: a word, #612, plan:558", "Wide view" and "?", and four columns: "Needs you 2" lit amber (a merge approval "Merge PR #612" with chips "high risk" "migration" and buttons "Approve", "Deny", "Split"; a question "#603 Which store for the session table?" with buttons "Postgres", "SQLite", "Ask the author"), "Queued 4", "In progress 5", "Done 8", each column head with a small ▾ at its right, the cards compact with a mono state row. No ticker at the foot."""

CONTENT = """What is new, and what this image is about: the factory runs routines, recurring work on a clock, and the member must see them before they file a card. The moment is Monday 05:40. The routines of this project, spelled exactly: "Weekly bump" · every Monday 06:00 · human card · next in 20 min · last Mon 6 Oct #781 merged; "Template pass" · hourly · pull request · last 05:03 no change; "Dependency update" · every Thursday 06:00 · agent card · next Thu · last Thu 9 Oct #779 merged; "Audit" · after 20 merges · agent card · 14 of 20 · last 2 Oct #702 3 findings. Two jobs of the cluster: "Backup" · daily 02:00 · last ok; "Forgejo dump" · daily 02:30 · last ok. In the Done column two cards carry a small mono chip "↻ routine": "#781 Weekly bump of the pinned outside inputs" and "#779 Dependency update". The acts on a routine are "Skip once" and "Run now" as small quiet buttons. A change of rhythm is proposed in the chat as a configuration change, never as a toggle."""

TAIL = """Legible UI text with exact spelling, nothing invented, no lorem ipsum. The pulse stays the loudest thing on the screen after the amber Needs you column; the chat stays the main region; the routines are quiet instruments in the muted colour, and the only loud marks are the ones the shell already has. Made by a top product design studio. Not a template, not a generic admin dashboard."""

D = [
 ("01-ghost-card", "Ghost card", """At the foot of the Queued column, under the four real queued cards, one card drawn with a dashed hairline border and no fill, its text in the faint colour: "↻ Weekly bump" as its title, the mono state row "due Mon 06:00 · in 20 min · human card", and two small ghost buttons "Skip once" "Run now". Under it a second, shorter dashed card "↻ Audit · after 6 more merges". The Queued head reads "Queued 4 · 2 due". No other new element: the board itself is the home of the routines, and a routine card's drawer would show a "Routine" section."""),
 ("02-panel-column", "Panel column", """The instrument strip is expanded: under it, inside the pulse band, the status panel shows four quiet columns split by hairlines with small-capitals heads in the faint colour: "In progress" (three card lines like "#601 Console: the drawer's Overview · building · 23 min"), "Needs you" (two lines), "Spend" (two small gauges "€4.82 of €10.00 day cap", "€61.40 of €120.00 month cap"), and the fourth column titled "Routines": one mono row per routine, "Weekly bump · Mon 06:00 · in 20 min", "Template pass · hourly · 05:03 no change", "Dependency update · Thu 06:00 · #779 merged", "Audit · after 20 merges · 14 of 20", then a hairline and "Backup 02:00 ok · Forgejo dump 02:30 ok" in the faint colour, and at the column's foot the configuration row "configuration v214 · a1f9c3e · provider ok · GitHub 1 open". The chat and the board below are unchanged and a little shorter."""),
 ("03-routines-page", "Routines page", """The top bar has one more link, "Routines", shown as the current page, and the whole area under the top bar is the Routines page: no pulse band, no board, no chat. A quiet table in the panel style with small-capitals heads "routine · rhythm · next · last run · outcome · open card" and four rows for Weekly bump, Template pass, Dependency update and Audit, each row with small quiet buttons "Skip once" and "Run now" at its right. The row "Weekly bump" is selected (the hover colour, a 2 px cyan left rule), and under the table a "Runs" list of six past runs as mono rows: the date, the card number, the outcome word in its hue (merged in green, no change in grey, 3 findings in amber), the duration, the cost. Under that a small "Jobs of the cluster" table with Backup and Forgejo dump. At the page's top right a faint line "rhythms are configuration: propose a change in the chat"."""),
 ("04-policy-in-force", "Policy in force", """The Policy page: the top bar's "Policy" is current, no pulse band, no board, no chat. Its head "configuration v214 · a1f9c3e · in force since Mon 05:03", then the existing stages table of the process "spec" (stage, findings go to, enabled, when), and beside it a new table titled "Routines" with heads "name · every · at · files · while open · tell · next · last", four rows for Weekly bump, Template pass, Dependency update and Audit with the configuration values in mono and the two live columns "next" and "last" at the right, and a faint link "edit in factory/routines.yaml" under the table. The jobs of the cluster in a second small table "Jobs" with "name · schedule · last run". A read-only page: no buttons anywhere."""),
 ("05-schedule-tape", "Schedule tape", """Under the instrument strip, inside the pulse band, a thin tape 28 px high across the band's width: a time axis of fourteen days in faint mono ("Mon 6" to "Sun 19") with today marked by a 1 px cyan line labelled "now"; past runs as small filled ticks in the outcome's hue (green for merged, grey for no change, amber for findings) on their day, future runs as hollow ticks in the faint colour (Weekly bump today at 06:00, Dependency update on Thu); the Audit, which has no day, as a small "audit 14/20" mark at the tape's right end. Each routine's name sits once in small mono at its first tick. One hovered tick shows a small tooltip panel "Weekly bump · Mon 06:00 · in 20 min · Skip once · Run now". The chat and the board below are unchanged and a little shorter."""),
 ("06-inbox-standing-row", "Inbox standing row", """The chat's open thread is the Inbox: its row in the thread table carries the house mark and is the open row, and the thread's head reads "Inbox" in amber with the line "the factory's thread: the agent speaks here uninvited". Pinned under the thread's head, above the log, a standing panel titled "Routines" in small capitals with four mono lines "Weekly bump · Mon 06:00 · in 20 min", "Template pass · hourly · 05:03 no change", "Dependency update · Thu 06:00 · next Thu", "Audit · after 20 merges · 14 of 20", each with two tiny ghost buttons "Skip once" "Run now" at its right. Below it the log with a turn by "the factory": "In 20 minutes I file the weekly bump card. Last week's #781 merged in 2 days." with a faint mono decider line "⚙ routine weekly-bump · every Monday 06:00" and choice buttons "Skip this week", "Run now", "Fine". The board at the right is unchanged."""),
 ("07-routine-drawer", "Routine drawer", """The drawer is open at the right edge over the board, and the chat stays visible at the left: the drawer's title "↻ Weekly bump" with the mono subtitle "routine · every Monday 06:00 · human card · next in 20 min", three tabs "Overview", "Runs", "Config" with Overview open: a four-line top block "next: Mon 06:00, in 20 min", "last: #781 merged in 2 days", "while open: hold", "tells: inbox", the buttons "Skip once" and "Run now" as quiet outlined buttons, then collapsed sections "The brief", "Runs (14)", "Config (factory/routines.yaml)". Behind the drawer the board's head carries a small "Routines ▾" menu beside the find box, and the visible done cards "#781" and "#779" carry the "↻ routine" chip."""),
 ("08-column-head", "Column head", """The only new element is in the Queued column's head: beside "Queued 4" a small mono line in the muted colour "↻ 2 due this week ▾", and its menu shown open as a small panel under the head: "Weekly bump · Mon 06:00 · in 20 min · Skip once · Run now", "Dependency update · Thu 06:00", a hairline, "Template pass · hourly · 05:03 no change", "Audit · after 20 merges · 14 of 20", a hairline, "Backup 02:00 ok · Forgejo dump 02:30 ok", and a faint foot "all routines ›". The other column heads stay as they are. Nothing else on the screen changes."""),
]
for slug, name, body in D:
    for theme in ("dark", "light"):
        t = "Dark theme." if theme == "dark" else "Light theme: the cream day version of the same design, dark navy text on warm off-white panels, the same cyan and amber."
        (R / f"{slug}-{theme}.txt").write_text(f"{HEAD}\n\n{CONTENT}\n\nDirection \"{name}\": {body} {t}\n\n{TAIL}\n")
print(len(D) * 2, "prompts")
